CustomField.formula:
IF( (RecordType.Name =='General' || RecordType.Name =='')  && !(ISPICKVAL(Status, "No Convertido") || ISPICKVAL(Status, "Convertido")),
    'Posibilidad Vigente',
       IF(RecordType.Name == 'Prospecto'  && (ISPICKVAL(StageName__c, "Cerrada Ganada")),
          'Cliente',
       IF((RecordType.Name == 'General' || RecordType.Name =='' )  && (ISPICKVAL(Status, "No Convertido")),
          'Descartado',
          IF(RecordType.Name == 'Prospecto'  && !(ISPICKVAL(StageName__c, "Cerrada Ganada") || ISPICKVAL(StageName__c, "Cerrada Perdida")),
       'Prospecto', ''
        )

    )
)
)
